        ["eye_dominance"] = ("Dominance {0}x (over {1}x, you lose the throne at ascension)", "주도권 {0}배 ({1}배를 넘으면 승천 때 주도권을 뺏김)"),
        ["eye_col_stat"] = ("Stat", "스탯"), ["eye_col_demiurge"] = ("Demiurge", "데미우르고스"), ["eye_col_me"] = ("You", "나"),
        ["eye_rest_calamity"] = ("Calamity while resting: the eyes of {0} took {2} from your highest stat, {1}.", "쉬는 동안 재앙: {0}의 눈동자가 가장 높은 스탯 {1}에서 {2}을(를) 빼앗았습니다."),
        ["eye_tree_title"] = ("Aeon Tree", "아이온 트리"), ["eye_points"] = ("Gnosis points {0}", "그노시스 포인트 {0}"),
        ["eye_tree_hint"] = ("Doctrine tiers open each level. Reach tier 9 first to choose your throne.", "교리 단계가 오르면 그 단계가 열립니다. 9단계에 먼저 이른 섹터가 승천할 왕좌가 됩니다."),
        ["eye_tree_empty"] = ("Choose a node to see what it does. Tap it again to learn.", "노드를 누르면 설명이 보입니다. 한 번 더 누르면 익힙니다."),
        ["eye_doctrine_level"] = ("Doctrine tier {0}", "교리 {0}단계"), ["eye_ascension_sector"] = ("Throne: {0}", "왕좌: {0}"),
        ["eye_level"] = ("Tier {0}", "{0}단계"), ["eye_start_tag"] = ("Granted by the golden eyes", "황금 눈동자가 내린 시작 스킬"),
        ["eye_kind_Good"] = ("Good aeon", "선한 아이온"), ["eye_kind_Evil"] = ("Evil aeon", "악한 아이온"), ["eye_kind_Gnosis"] = ("Gnosis", "그노시스"), ["eye_kind_Ascension"] = ("Ascension", "승천"),
        ["eye_eff_calamity"] = ("Calamity counter +{0} each quarter", "분기마다 재앙 카운터 +{0}"),
        ["eye_eff_calamity_guard"] = ("Calamity damage -{0}%, this sector's counter -1", "재앙 피해 -{0}%, 이 섹터 카운터 -1"),
        ["eye_need_doctrine"] = ("Needs doctrine tier {0}", "교리 {0}단계 필요"), ["eye_need_points"] = ("Not enough points", "포인트 부족"),
        ["eye_need_ascension"] = ("Another sector reached the threshold first", "다른 섹터가 먼저 문턱에 이름"),
        ["eye_need_start"] = ("Answer the golden eyes first", "먼저 눈동자 질문에 답해야 함"),
        ["eye_need_both"] = ("Learn both tier-4 aeons first", "4단계 선·악 아이온을 모두 익혀야 함"),
        ["eye_need_below"] = ("Learn the tier below first", "아래 단계를 먼저 익혀야 함"),
        ["eye_question"] = ("Whose were the burning golden eyes that looked upon you?", "당신을 바라본 불타는 황금의 눈동자는 누구의 것이었는가."),
        ["eye_sector_yahweh"] = ("Yahweh", "야훼"), ["eye_sector_yahweh_answer"] = ("The jealous eyes that carved the Law", "율법을 새긴 질투하는 눈"),
        ["eye_sector_satan"] = ("Satan", "사탄"), ["eye_sector_satan_answer"] = ("The eyes of the Accuser, counting every sin", "죄를 헤아리는 고발자의 눈"),
        ["eye_sector_samael"] = ("Samael", "사마엘"), ["eye_sector_samael_answer"] = ("The eyes of the blind god, who sees nothing", "앞을 보지 못하는 눈먼 신의 눈"),
        ["eye_sector_yaldabaoth"] = ("Yaldabaoth", "얄다바오트"), ["eye_sector_yaldabaoth_answer"] = ("Serpent eyes set in a lion's face", "사자의 얼굴에 박힌 뱀의 눈"),
        ["god_tutorial"] = ("A god has descended into a mortal vessel. Open the Divine Tree and choose your nature.", "신이 인간의 그릇에 강림했습니다. 권능 트리를 열어 신의 본성을 고르십시오."),
        ["end_name_god_miracle_mercy"] = ("The Healing God", "치유하는 신"), ["end_desc_god_miracle_mercy"] = ("Ascended through Miracle and Mercy.", "기적과 자비로 승천함."),
        ["end_text_god_miracle_mercy"] = ("{0} raised its god after {1} years. The sick rose from their beds, and no one went hungry again.\nThey were happy. Whether that was salvation, no one asked.", "{0}의 신은 {1}년 만에 승천했습니다. 병든 이들이 자리에서 일어났고, 다시는 굶는 이가 없었습니다.\n그들은 행복했습니다. 그것이 구원이었는지는, 아무도 묻지 않았습니다."),
        ["end_name_god_miracle_desire"] = ("The God of Revelry", "향락의 신"), ["end_desc_god_miracle_desire"] = ("Ascended through Miracle and Desire.", "기적과 욕망으로 승천함."),
        ["end_text_god_miracle_desire"] = ("After {1} years, {0} became an endless feast. Wine never ran dry, and every night was holy.\nThey were happy. Whether that was salvation, no one asked.", "{1}년 뒤, {0}은 끝나지 않는 연회가 되었습니다. 술잔은 마르지 않았고, 모든 밤이 성스러웠습니다.\n그들은 행복했습니다. 그것이 구원이었는지는, 아무도 묻지 않았습니다."),
        ["end_name_god_prophecy_mercy"] = ("The Guiding God", "인도하는 신"), ["end_desc_god_prophecy_mercy"] = ("Ascended through Prophecy and Mercy.", "예언과 자비로 승천함."),
        ["end_text_god_prophecy_mercy"] = ("For {1} years {0} listened. Now the god's voice walks ahead of every follower, and no one is ever lost.\nThey were happy. Whether they still chose their own road, no one asked.", "{1}년 동안 {0}은 귀를 기울였습니다. 이제 신의 목소리가 모든 신도의 앞길을 걷고, 길을 잃는 이는 없습니다.\n그들은 행복했습니다. 아직 스스로 길을 고르는지는, 아무도 묻지 않았습니다."),
        ["end_name_god_prophecy_desire"] = ("The Tempting God", "유혹하는 신"), ["end_desc_god_prophecy_desire"] = ("Ascended through Prophecy and Desire.", "예언과 욕망으로 승천함."),
        ["end_text_god_prophecy_desire"] = ("After {1} years, the god of {0} whispers what each heart wants most, and promises it.\nThey were happy. Whether the promises were kept, no one asked.", "{1}년 뒤, {0}의 신은 모든 이의 마음이 가장 원하는 것을 속삭이고, 그것을 약속합니다.\n그들은 행복했습니다. 약속이 지켜졌는지는, 아무도 묻지 않았습니다."),
        ["end_name_god_divine"] = ("The God Who Shed Humanity", "인간을 벗은 신"), ["end_desc_god_divine"] = ("?", "?"),
        ["end_text_god_divine"] = ("After {1} years the vessel was empty. The god of {0} rose without looking back at the body it wore.\nThe followers still pray to the empty chair. Whether anyone hears, no one asks.", "{1}년 뒤 그릇은 비었습니다. {0}의 신은 입었던 몸을 돌아보지 않고 떠올랐습니다.\n신도들은 아직도 빈 의자에 기도합니다. 누가 듣고 있는지는, 아무도 묻지 않습니다."),
        ["end_name_god_human"] = ("The God on the Threshold", "경계 위의 신"), ["end_desc_god_human"] = ("?", "?"),
        ["end_text_god_human"] = ("After {1} years the god of {0} chose to stay, half divine, half the person it borrowed. It laughs, weeps, and blesses.\nThey were happy. Whether it was a god or a person, no one asked.", "{1}년 뒤 {0}의 신은 반은 신으로, 반은 빌린 사람으로 남기를 택했습니다. 웃고, 울고, 축복합니다.\n그들은 행복했습니다. 그것이 신인지 사람인지는, 아무도 묻지 않았습니다."),
        ["end_name_god_vessel"] = ("Collapse of the Vessel", "그릇의 붕괴"), ["end_desc_god_vessel"] = ("The host's body or mind gave out.", "숙주의 체력이나 정신이 다함."),
        ["end_text_god_vessel"] = ("In year {1} of {0}, the borrowed body could hold no more. The god slipped out like water from a cracked jar.", "{0} {1}년, 빌린 몸은 더 버티지 못했습니다. 신은 금 간 항아리의 물처럼 흘러나갔습니다."),
        ["end_name_god_forgotten"] = ("The Forgotten God", "잊힌 신"), ["end_desc_god_forgotten"] = ("No followers or no faith remained.", "신도나 신도의 믿음이 바닥남."),
        ["end_text_god_forgotten"] = ("In year {1} of {0}, the last prayer stopped. Other gods smiled. A god no one remembers is no god at all.", "{0} {1}년, 마지막 기도가 멈췄습니다. 다른 신들이 미소 지었습니다. 아무도 기억하지 않는 신은 신이 아닙니다."),
        ["end_name_god_disbanded"] = ("The Disbanded Cult", "해산된 교단"), ["end_desc_god_disbanded"] = ("The state ordered the cult dissolved.", "국가의 명령으로 해산됨."),
        ["end_text_god_disbanded"] = ("In year {1} of {0}, the state sealed the doors. The miracles were filed away as fraud.", "{0} {1}년, 국가가 문을 봉했습니다. 기적들은 사기 사건 서류철에 묶였습니다."),
        ["god_need_points"] = ("Not enough points", "포인트가 부족합니다"), ["god_ascended"] = ("Ascended", "승천 완료"),
        ["god_tree_hint"] = ("From the outer ring inward", "바깥 고리부터 안쪽으로"),
        ["god_tree_empty"] = ("Select a node to see its effect and cost. Double-click to learn.", "노드를 누르면 효과와 비용이 보임. 두 번 누르면 익힘."),
        ["god_eff_gain"] = ("{0} gains +{1}%", "{0} 증가량 +{1}%"), ["god_eff_guard"] = ("{0} losses -{1}%", "{0} 감소량 -{1}%"),
        ["god_eff_chance"] = ("{0} success +{1}%p", "{0} 성공률 +{1}%p"), ["god_eff_resist"] = ("{0} pressure gain and damage -{1}%", "{0} 압박 상승·피해 -{1}%"),
        ["god_eff_seize"] = ("Block seizure {0}%", "압류 방어 {0}%"), ["god_eff_commune"] = ("Miracle communion cost -{0}%", "기적의 접신 소모 -{0}%"),
        ["god_eff_vessel"] = ("Feast vessel recovery +{0}%", "향연의 그릇 회복 +{0}%"), ["god_eff_faith"] = ("Faith points +{0}%", "신앙 비례 포인트 +{0}%"),
        ["god_eff_year"] = ("Every year {0} {1}", "해마다 {0} {1}"),
        ["god_pressure_Heaven"] = ("Heaven", "신계"), ["god_pressure_Earth"] = ("Earth", "지상"),
        ["god_act_Wonder"] = ("Wonder", "이적"), ["god_act_Revelation"] = ("Revelation", "계시"), ["god_act_Healing"] = ("Healing", "치유"),
        ["god_act_Feast"] = ("Feast", "향연"), ["god_act_Commune"] = ("Commune", "교감"), ["god_act_Consecrate"] = ("Consecrate", "축성"),
        ["god_act_All"] = ("All actions", "모든 행동"),
        // 준비된 신: 축성(봉헌 건축)·성인 확인
        ["god_building_Statue"] = ("Statue", "조각상"), ["god_building_Temple"] = ("Temple", "신전"), ["god_building_Library"] = ("Scripture Hall", "경전관"),
        ["god_building_Village"] = ("Commune", "공동체 마을"), ["god_building_Shelter"] = ("Relief House", "구호소"),
        ["god_consecrate_title"] = ("Consecration", "축성"),
        ["god_build_hint"] = ("Raise a building by miracle. It uses this turn's action.", "기적으로 건물을 세웁니다. 이번 분기의 행동을 씁니다."),
        ["god_build_wait"] = ("You can consecrate only on an action turn.", "행동을 고를 차례에만 축성할 수 있습니다."),
        ["god_build_info"] = ("Keeps {0} at least {1} · upkeep {2}/year", "{0} 최소 {1} 유지 · 유지비 해마다 {2}"),
        ["god_build_next"] = ("Consecrate ({0} offerings, {1} communion)", "축성 (봉헌금 {0}, 접신 {1})"),
        ["god_build_stage"] = ("Reach the {0} stage", "'{0}' 단계 필요"), ["god_build_offerings"] = ("Need {0} offerings", "봉헌금 {0} 필요"),
        ["god_build_communion"] = ("Not enough communion", "접신 부족"), ["god_build_max"] = ("Fully raised", "최고 단계"),
        ["god_build_locked"] = ("Unlock in the Wealth area of the Divine Tree", "권능 트리 재력 구역에서 해금"),
        ["god_consecrated"] = ("You consecrated the {0}. (Lv.{1})", "{0}을(를) 축성했습니다. (Lv.{1})"),
        ["god_eff_build"] = ("Unlocks building: {0}", "건물 해금: {0}"),
        ["god_broad"] = ("Breadth ×{0}", "단계 보너스 ×{0}"),
        ["god_adult_confirm"] = ("This mode contains sensual and decadent scenes.\nAre you an adult?", "이 모드에는 관능적이고 퇴폐적인 묘사가 있습니다.\n성인입니까?"),
        ["god_adult_ok"] = ("I am an adult", "성인입니다"),
        ["quiz_dissolved"] = ("When your standing sinks to nothing, the state takes the cult away.", "명망이 바닥나면 나라가 교단을 거둔다."),
        ["quiz_death_young"] = ("Before a cult is founded, the years may close the book.", "교단을 세우기도 전에, 나이가 먼저 판을 닫는다."),
        ["quiz_death_leader"] = ("While the cult still stands, the leader's years may end the story.", "교단이 서 있는 동안, 교주의 나이가 판을 닫는다."),
        ["quiz_extreme"] = ("When {0} reaches its {1} point and {2} years pass.", "{0}이(가) {1} 자리에 닿은 채 {2}년이 흐르면."),
        ["quiz_high"] = ("highest", "가장 높은"), ["quiz_low"] = ("lowest", "바닥의"),
        ["quiz_final"] = ("When the {0} branch rises above {1}, and the average of {2} is {3}.", "{0} 가지가 {1}을 넘는 날, 반대편 {2}의 평균이 {3}."),
        ["quiz_over50"] = ("over 50", "50을 넘을 때"), ["quiz_under50"] = ("50 or less", "50 이하일 때"),
        ["end_tag_good"] = ("Good ending", "굿 엔딩"),
        ["end_tag_bad"] = ("Bad ending", "배드 엔딩"),
        ["end_name_Temperance_good"] = ("Sanctuary of Restraint", "절제의 성지"),
        ["end_desc_Temperance_good"] = ("Your cult became a quiet holy ground where desire was set aside.", "모든 욕심을 내려놓은 교단은 고요한 성지로 기억된다."),
        ["end_text_Temperance_good"] = ("The leader of '{0}' set every craving aside, and after {1} years of discipline the followers found peace in its quiet order. Your cult is remembered as a holy ground of restraint.", "교주는 모든 욕심을 내려놓았고, 신도들은 '{0}'의 고요한 질서 속에서 평화를 찾았습니다. {1}년의 수행 끝에 교단은 절제의 성지로 기억됩니다."),
        ["end_name_Charity_good"] = ("The Saint of Mercy", "자애의 성인"),
        ["end_desc_Charity_good"] = ("The love you gave for years changed the city, and people call you a saint.", "오랜 베풂이 도시를 바꾸었고 사람들은 교주를 성인이라 부른다."),
        ["end_text_Charity_good"] = ("The doors of '{0}' were open to everyone. Over {1} years your kindness changed the city, and people now call you a saint.", "'{0}'의 문은 누구에게나 열려 있었습니다. {1}년 동안 베푼 사랑이 도시를 바꾸었고, 사람들은 교주를 성인이라 부릅니다."),
        ["end_name_Patience_good"] = ("The Fruit of Patience", "인내의 열매"),
        ["end_desc_Patience_good"] = ("After countless trials endured in silence, the world accepted your teaching.", "수많은 시련을 묵묵히 견딘 끝에 세상이 가르침을 받아들였다."),
        ["end_text_Patience_good"] = ("'{0}' endured every trial in silence. After {1} years of waiting, the world finally accepted its teaching.", "수많은 시련을 묵묵히 견딘 '{0}'. {1}년의 기다림 끝에 세상이 교단의 가르침을 받아들였습니다."),
        ["end_name_Integrity_good"] = ("A Model of Integrity", "청렴의 본보기"),
        ["end_desc_Integrity_good"] = ("Not a single coin was misused, and the cult became the standard of its age.", "한 푼의 부정도 없던 교단은 시대의 본보기가 되었다."),
        ["end_text_Integrity_good"] = ("Not a single coin of '{0}' was ever misused. After {1} years of transparent management, everyone trusts it, and your cult has become the model of an age.", "한 푼의 부정도 없던 '{0}'. {1}년의 투명한 운영이 모두의 신뢰를 얻어, 교단은 시대의 본보기가 됩니다."),
        ["end_name_Lust_bad"] = ("Ruin by Pleasure", "쾌락의 파멸"),
        ["end_desc_Lust_bad"] = ("The leader drowned in pleasure, and the cult collapsed as a den of debauchery.", "교주는 쾌락에 빠졌고 교단은 방탕의 소굴로 무너졌다."),
        ["end_text_Lust_bad"] = ("The leader of '{0}' drowned in pleasure and turned the sanctuary into a private palace. After {1} years the cult was called a den of debauchery, and it collapsed.", "교주는 쾌락에 빠져 '{0}'을 사당처럼 꾸몄습니다. {1}년 만에 교단은 방탕의 소굴이라 불리며 무너졌습니다."),
        ["end_name_Greed_bad"] = ("Ruin by Gold", "황금의 파멸"),
        ["end_desc_Greed_bad"] = ("Your ledgers were exposed and the cult went bankrupt.", "장부가 폭로되며 교단은 파산했다."),
        ["end_text_Greed_bad"] = ("'{0}' squeezed its followers for every last coin. After {1} years the ledgers were exposed, and the cult went bankrupt.", "금고를 채우려 신도의 마지막 한 푼까지 거두던 '{0}'. {1}년 만에 장부가 폭로되며 교단은 파산했습니다."),
        ["end_name_Appetite_bad"] = ("Ruin by Gluttony", "탐식의 파멸"),
        ["end_desc_Appetite_bad"] = ("Endless feasts emptied the storehouses and the starving followers left.", "끝없는 연회로 곳간이 비자 굶주린 신도들이 떠났다."),
        ["end_text_Appetite_bad"] = ("Endless feasts emptied the storehouses of '{0}'. After {1} years the starving followers abandoned their leader.", "끝없는 성찬과 연회로 '{0}'의 곳간은 비었고, {1}년 만에 굶주린 신도들은 교주를 떠났습니다."),
        ["end_name_Ambition_bad"] = ("Ruin by the Throne", "권좌의 파멸"),
        ["end_desc_Ambition_bad"] = ("Your attempt to seize the throne failed and the cult was branded traitors.", "왕좌를 노린 시도가 실패해 교단은 반역자로 낙인찍혔다."),
        ["end_text_Ambition_bad"] = ("'{0}' reached for the throne in the name of its god. After {1} years the coup failed, and the cult was branded a band of traitors.", "신의 이름으로 왕좌를 노린 '{0}'. {1}년 만에 쿠데타는 실패하고 교단은 반역자의 교단으로 낙인찍혔습니다."),
        ["end_name_Lust_good"] = ("Passion Made Holy", "열정의 승화"),
        ["end_desc_Lust_good"] = ("Desire was turned into devotion, and your cult became a place of warm, bright love.", "욕망을 헌신으로 바꾼 교단은 뜨겁고 밝은 사랑의 장소가 되었다."),
        ["end_text_Lust_good"] = ("The leader of '{0}' turned passion into devotion. After {1} years, the way of {2} led people to warm, honest love, and the cult is remembered as a place of joy.", "음욕을 헌신의 열정으로 바꾼 '{0}'. {1}년 끝에 '{2}'의 길은 사람들을 뜨겁고 정직한 사랑으로 이끌었고, 교단은 기쁨의 장소로 기억됩니다."),
        ["end_name_Greed_good"] = ("A Wealth Shared", "풍요의 나눔"),
        ["end_desc_Greed_good"] = ("The wealth you gathered fed the whole city.", "모은 재물이 도시 전체를 먹여 살렸다."),
        ["end_text_Greed_good"] = ("'{0}' gathered wealth, then gave it away. After {1} years, the way of {2} had fed the whole city, and no one in it went hungry.", "재물을 모아 모두에게 나눈 '{0}'. {1}년 끝에 '{2}'의 길은 도시 전체를 먹여 살렸고, 누구도 굶주리지 않게 되었습니다."),
        ["end_name_Appetite_good"] = ("A Table of Peace", "식탁의 평화"),
        ["end_desc_Appetite_good"] = ("The great feasts became a table open to everyone, and hunger disappeared.", "성대한 연회는 모두의 식탁이 되어 굶주림이 사라졌다."),
        ["end_text_Appetite_good"] = ("The feasts of '{0}' became a table for everyone. After {1} years, the way of {2} had ended hunger across the land.", "'{0}'의 연회는 모두의 식탁이 되었습니다. {1}년 끝에 '{2}'의 길은 온 땅에서 굶주림을 몰아냈습니다."),
        ["end_name_Ambition_good"] = ("A Just Crown", "정의로운 왕관"),
        ["end_desc_Ambition_good"] = ("Your cult held power and used it to build justice.", "권력을 쥔 교단이 그 힘으로 정의를 세웠다."),
        ["end_text_Ambition_good"] = ("'{0}' gained great power and used it for justice. After {1} years, the way of {2} had changed the laws of the land, and the people call it a just crown.", "큰 권력을 얻은 '{0}'은 그 힘으로 정의를 세웠습니다. {1}년 끝에 '{2}'의 길은 나라의 법을 바꾸었고, 사람들은 그것을 정의로운 왕관이라 부릅니다."),
        ["end_name_Temperance_bad"] = ("Cold Asceticism", "차가운 금욕"),
        ["end_desc_Temperance_bad"] = ("Restraint hardened into oppression, and the followers left in silence.", "절제가 억압으로 굳어 신도들은 말없이 떠났다."),
        ["end_text_Temperance_bad"] = ("The restraint of '{0}' hardened into oppression. After {1} years of the rigid way of {2}, the followers quietly left, and the sanctuary stood empty.", "절제가 억압으로 굳어 버린 '{0}'. {1}년 동안 '{2}'의 엄격한 길을 강요받은 신도들은 조용히 떠났고, 성소는 텅 비었습니다."),
        ["end_name_Charity_bad"] = ("Blind Mercy", "맹목의 자비"),
        ["end_desc_Charity_bad"] = ("Giving without discernment emptied the storehouses and the cult was exploited until it fell.", "분별없는 베풂으로 곳간이 비고 이용만 당하다 무너졌다."),
        ["end_text_Charity_bad"] = ("'{0}' gave without discernment. After {1} years, the way of {2} had been exploited by schemers until the storehouses were empty, and the cult fell.", "분별없이 베풀던 '{0}'. {1}년 끝에 '{2}'의 길은 속이는 자들에게 이용당했고, 곳간이 비어 교단은 쓰러졌습니다."),
        ["end_name_Patience_bad"] = ("A Silence of Resignation", "체념의 침묵"),
        ["end_desc_Patience_bad"] = ("Endurance became silence before injustice, and the cult became an accomplice.", "참음이 불의 앞의 침묵이 되어 교단은 공범이 되었다."),
        ["end_text_Patience_bad"] = ("'{0}' only endured. After {1} years, the way of {2} stayed silent before every injustice, and the cult became an accomplice to it.", "참기만 하던 '{0}'. {1}년 끝에 '{2}'의 길은 모든 불의 앞에서 침묵했고, 교단은 그 불의의 공범이 되었습니다."),
        ["end_name_Integrity_bad"] = ("Self-Righteous Judgment", "독선의 심판"),
        ["end_desc_Integrity_bad"] = ("Purity became arrogance, and by judging everyone the cult isolated itself.", "청렴이 독선이 되어 모두를 심판하다 스스로 고립되었다."),
        ["end_text_Integrity_bad"] = ("The purity of '{0}' turned into arrogance. After {1} years, the way of {2} had put every neighbor on trial, and the cult stood alone.", "청렴이 독선이 된 '{0}'. {1}년 끝에 '{2}'의 길은 이웃을 모두 심판대에 세웠고, 교단은 홀로 남았습니다."),
        ["doctrine_final_taken"] = ("Another final skill was already chosen", "다른 최종 스킬을 이미 골랐음"),
        ["end_name_extreme_LeaderFaith_max"] = ("Blazing Conviction", "광신의 교주"),
        ["end_desc_extreme_LeaderFaith_max"] = ("Only the leader's faith burned without end, and the whole cult staked everything on one person's certainty.", "교주의 신앙만이 끝없이 타올라, 교단은 교주 한 사람의 확신에 모든 것을 걸었습니다."),
        ["end_text_extreme_LeaderFaith_max"] = ("{1} years passed, but '{0}' never chose its highest path. Only the leader's faith burned without end, and the whole cult staked everything on one person's certainty.", "{1}년이 흘렀지만 '{0}'은 끝내 가장 높은 길을 고르지 못했습니다. 교주의 신앙만이 끝없이 타올라, 교단은 교주 한 사람의 확신에 모든 것을 걸었습니다."),
        ["end_name_extreme_LeaderFaith_min"] = ("Shattered Certainty", "무너진 확신"),
        ["end_desc_extreme_LeaderFaith_min"] = ("The leader could no longer believe in the god, and the cult closed its doors in doubt.", "교주는 끝내 신을 믿지 못하게 되었고, 교단은 의심 속에 문을 닫았습니다."),
        ["end_text_extreme_LeaderFaith_min"] = ("{1} years passed, but '{0}' never chose its highest path. The leader could no longer believe in the god, and the cult closed its doors in doubt.", "{1}년이 흘렀지만 '{0}'은 끝내 가장 높은 길을 고르지 못했습니다. 교주는 끝내 신을 믿지 못하게 되었고, 교단은 의심 속에 문을 닫았습니다."),
        ["end_name_extreme_FollowerFaith_max"] = ("One Heart of Believers", "한마음의 신도"),
        ["end_desc_extreme_FollowerFaith_max"] = ("The believers' faith gathered into a single point, and the cult became an unshakable community.", "신도들의 믿음이 한 점으로 모여, 교단은 흔들림 없는 신앙 공동체가 되었습니다."),
        ["end_text_extreme_FollowerFaith_max"] = ("{1} years passed, but '{0}' never chose its highest path. The believers' faith gathered into a single point, and the cult became an unshakable community.", "{1}년이 흘렀지만 '{0}'은 끝내 가장 높은 길을 고르지 못했습니다. 신도들의 믿음이 한 점으로 모여, 교단은 흔들림 없는 신앙 공동체가 되었습니다."),
        ["end_name_extreme_FollowerFaith_min"] = ("Faith Gone Cold", "식어 버린 믿음"),
        ["end_desc_extreme_FollowerFaith_min"] = ("Every believer's faith went cold, and the pews stood empty.", "신도들의 믿음이 모두 식어 신도석은 텅 비었습니다."),
        ["end_text_extreme_FollowerFaith_min"] = ("{1} years passed, but '{0}' never chose its highest path. Every believer's faith went cold, and the pews stood empty.", "{1}년이 흘렀지만 '{0}'은 끝내 가장 높은 길을 고르지 못했습니다. 신도들의 믿음이 모두 식어 신도석은 텅 비었습니다."),
        ["end_name_extreme_Authority_max"] = ("Absolute Authority", "절대 권위"),
        ["end_desc_extreme_Authority_max"] = ("The cult's authority reached the sky, and no one dared defy the leader.", "교단의 권위가 하늘에 닿아 누구도 교주의 말을 거스르지 못했습니다."),
        ["end_text_extreme_Authority_max"] = ("{1} years passed, but '{0}' never chose its highest path. The cult's authority reached the sky, and no one dared defy the leader.", "{1}년이 흘렀지만 '{0}'은 끝내 가장 높은 길을 고르지 못했습니다. 교단의 권위가 하늘에 닿아 누구도 교주의 말을 거스르지 못했습니다."),
        ["end_name_extreme_Authority_min"] = ("Forgotten Authority", "잊힌 권위"),
        ["end_desc_extreme_Authority_min"] = ("The leader's words became an echo that no one followed.", "교주의 말은 더 이상 아무도 따르지 않는 메아리가 되었습니다."),
        ["end_text_extreme_Authority_min"] = ("{1} years passed, but '{0}' never chose its highest path. The leader's words became an echo that no one followed.", "{1}년이 흘렀지만 '{0}'은 끝내 가장 높은 길을 고르지 못했습니다. 교주의 말은 더 이상 아무도 따르지 않는 메아리가 되었습니다."),
        ["end_name_extreme_Offerings_max"] = ("A Golden Storehouse", "황금 곳간"),
        ["end_desc_extreme_Offerings_max"] = ("Offerings filled the storehouse, and the cult became a castle of wealth.", "헌금이 곳간을 가득 채워 교단은 부유함의 성이 되었습니다."),
        ["end_text_extreme_Offerings_max"] = ("{1} years passed, but '{0}' never chose its highest path. Offerings filled the storehouse, and the cult became a castle of wealth.", "{1}년이 흘렀지만 '{0}'은 끝내 가장 높은 길을 고르지 못했습니다. 헌금이 곳간을 가득 채워 교단은 부유함의 성이 되었습니다."),
        ["end_name_extreme_Offerings_min"] = ("An Empty Storehouse", "텅 빈 곳간"),
        ["end_desc_extreme_Offerings_min"] = ("The storehouse ran dry, and the cult could no longer keep itself running.", "곳간이 바닥나 교단은 더는 살림을 이어갈 수 없었습니다."),
        ["end_text_extreme_Offerings_min"] = ("{1} years passed, but '{0}' never chose its highest path. The storehouse ran dry, and the cult could no longer keep itself running.", "{1}년이 흘렀지만 '{0}'은 끝내 가장 높은 길을 고르지 못했습니다. 곳간이 바닥나 교단은 더는 살림을 이어갈 수 없었습니다."),
        ["end_name_extreme_Followers_max"] = ("A Cult of Multitudes", "인파의 교단"),
        ["end_desc_extreme_Followers_max"] = ("A tide of followers filled the city, and the cult became the current of an age.", "신도의 물결이 도시를 메워 교단은 시대의 흐름이 되었습니다."),
        ["end_text_extreme_Followers_max"] = ("{1} years passed, but '{0}' never chose its highest path. A tide of followers filled the city, and the cult became the current of an age.", "{1}년이 흘렀지만 '{0}'은 끝내 가장 높은 길을 고르지 못했습니다. 신도의 물결이 도시를 메워 교단은 시대의 흐름이 되었습니다."),
        ["end_name_extreme_Followers_min"] = ("A Leader Alone", "홀로 남은 교주"),
        ["end_desc_extreme_Followers_min"] = ("The followers left one by one, and only the leader remained.", "신도가 한 명 한 명 떠나 교주만이 남았습니다."),
        ["end_text_extreme_Followers_min"] = ("{1} years passed, but '{0}' never chose its highest path. The followers left one by one, and only the leader remained.", "{1}년이 흘렀지만 '{0}'은 끝내 가장 높은 길을 고르지 못했습니다. 신도가 한 명 한 명 떠나 교주만이 남았습니다."),
        ["end_name_extreme_Doctrine_max"] = ("A Perfected Doctrine", "완성된 교리"),
        ["end_desc_extreme_Doctrine_max"] = ("The doctrine was completed without a gap, and the cult became a school of thought.", "교리가 빈틈없이 완성되어 교단은 하나의 학문이 되었습니다."),
        ["end_text_extreme_Doctrine_max"] = ("{1} years passed, but '{0}' never chose its highest path. The doctrine was completed without a gap, and the cult became a school of thought.", "{1}년이 흘렀지만 '{0}'은 끝내 가장 높은 길을 고르지 못했습니다. 교리가 빈틈없이 완성되어 교단은 하나의 학문이 되었습니다."),
        ["end_name_extreme_Doctrine_min"] = ("A Vanished Teaching", "사라진 가르침"),
        ["end_desc_extreme_Doctrine_min"] = ("The teaching was forgotten, and only the name of the cult remained.", "가르침이 잊혀 교단에는 이름만 남았습니다."),
        ["end_text_extreme_Doctrine_min"] = ("{1} years passed, but '{0}' never chose its highest path. The teaching was forgotten, and only the name of the cult remained.", "{1}년이 흘렀지만 '{0}'은 끝내 가장 높은 길을 고르지 못했습니다. 가르침이 잊혀 교단에는 이름만 남았습니다."),
